import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('schema compilation', () => {
    it('validates function-valued schema against the schema at each call', async () => {
      const registry = new ToolRegistry();
      let schemaVersions = 0;

      registry.register(
        () => {
          schemaVersions += 1;
          return {
            name: 'dynamic_tool',
            description: 'Tool with dynamic schema',
            inputSchema: {
              type: 'object',
              properties: {id: {type: 'string'}},
              required: ['id'],
            },
          };
        },
        async input => `id: ${String(input.id)}`
      );

      const result1 = await registry.execute('dynamic_tool', {id: 'first'});
      const result2 = await registry.execute('dynamic_tool', {id: 'second'});

      expect({
        result1: result1.result,
        result2: result2.result,
        schemaResolvedForEachCall: schemaVersions >= 2,
      }).toEqual({
        result1: 'id: first',
        result2: 'id: second',
        schemaResolvedForEachCall: true,
      });
    });

    it('formats type validation errors with field name and type but not value', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'test_tool',
          description: 'Test tool',
          inputSchema: {
            type: 'object',
            properties: {ssn: {type: 'string'}},
            required: ['ssn'],
          },
        },
        async () => 'unreachable'
      );

      const response = await registry.execute('test_tool', {ssn: 123456789});
      expect({
        hasFieldName: response.result.includes('ssn'),
        hasExpectedType: response.result.includes('string'),
        leaksValue: response.result.includes('123456789'),
      }).toMatchObject({
        hasFieldName: true,
        hasExpectedType: true,
        leaksValue: false,
      });
    });

    it('compiles static tool schema once across multiple execute calls', async () => {
      const registry = new ToolRegistry();
      let compileCount = 0;
      const originalAjv = registry['ajv'];
      const originalCompile = originalAjv.compile;
      let actualCompileCount = 0;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      originalAjv.compile = function (this: any, schema: Record<string, unknown>) {
        actualCompileCount += 1;
        return originalCompile.call(this, schema);
      };

      registry.register(
        {
          name: 'static_tool',
          description: 'Static tool',
          inputSchema: {
            type: 'object',
            properties: {value: {type: 'number'}},
            required: ['value'],
          },
        },
        async input => `value: ${String(input.value)}`
      );

      const compileCountAfterRegister = actualCompileCount;

      // Call execute multiple times
      const results = [];
      for (let i = 0; i < 10; i++) {
        results.push(await registry.execute('static_tool', {value: i}));
      }

      // Verify schema was only compiled once (at register time), not for each execute
      expect({
        compiledOnceAtRegister: compileCountAfterRegister >= 1,
        executedTenTimes: results.length === 10,
        noAdditionalCompiles: actualCompileCount === compileCountAfterRegister,
      }).toEqual({
        compiledOnceAtRegister: true,
        executedTenTimes: true,
        noAdditionalCompiles: true,
      });
    });
  });
});

